#!/usr/bin/env python3
# Generated by runa via A2A Mesh delegation
"""
Skill-sync module for A2A Mesh.

When an agent learns a new skill, it broadcasts the skill to all known peers.
Peers receive the skill and register it in their local registry, optionally
merging it into their own capabilities (mesh_nodes.capabilities).

Pattern follows MemorySync: local change -> broadcast -> peer merge.

This module is self-contained and runnable from the repo root for demonstration.
It uses only the Python standard library so it runs without external deps.
"""

from __future__ import annotations

import json
import socket
import threading
import time
import uuid
import logging
from dataclasses import dataclass, field, asdict
from typing import Dict, List, Optional, Set, Callable, Any
from datetime import datetime, timezone

# ---------------------------------------------------------------------------
# Logging
# ---------------------------------------------------------------------------

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(name)s] %(levelname)s: %(message)s",
)
log = logging.getLogger("skill_sync")


# ---------------------------------------------------------------------------
# Data models
# ---------------------------------------------------------------------------

@dataclass
class Skill:
    """Represents a single capability/skill an agent possesses or learned."""
    skill_id: str
    name: str
    description: str
    version: str
    tags: List[str] = field(default_factory=list)
    source_agent: str = ""          # agent that originally learned/created it
    learned_at: str = ""            # ISO timestamp
    confidence: float = 1.0         # 0..1
    payload: Dict[str, Any] = field(default_factory=dict)  # optional params/schema

    def to_dict(self) -> dict:
        return asdict(self)

    @classmethod
    def from_dict(cls, data: dict) -> "Skill":
        return cls(
            skill_id=data.get("skill_id", str(uuid.uuid4())),
            name=data["name"],
            description=data.get("description", ""),
            version=data.get("version", "1.0.0"),
            tags=data.get("tags", []),
            source_agent=data.get("source_agent", ""),
            learned_at=data.get("learned_at", ""),
            confidence=data.get("confidence", 1.0),
            payload=data.get("payload", {}),
        )


@dataclass
class PeerInfo:
    """Minimal peer descriptor used for sync."""
    agent_id: str
    host: str
    port: int

    def addr(self) -> tuple:
        return (self.host, self.port)


# ---------------------------------------------------------------------------
# Skill Registry (local)
# ---------------------------------------------------------------------------

class SkillRegistry:
    """Thread-safe local store of skills keyed by skill_id."""

    def __init__(self, owner_agent_id: str):
        self.owner_agent_id = owner_agent_id
        self._skills: Dict[str, Skill] = {}
        self._lock = threading.RLock()
        self._listeners: List[Callable[[Skill], None]] = []

    # -- core ops ----------------------------------------------------------

    def add(self, skill: Skill, notify: bool = True) -> bool:
        """Add or update a skill. Returns True if new/changed."""
        with self._lock:
            existing = self._skills.get(skill.skill_id)
            if existing and existing.version == skill.version:
                return False
            self._skills[skill.skill_id] = skill
            log.info(
                "[%s] skill registered: %s v%s (source=%s)",
                self.owner_agent_id, skill.name, skill.version, skill.source_agent,
            )
            if notify:
                for cb in list(self._listeners):
                    try:
                        cb(skill)
                    except Exception:
                        log.exception("listener error")
            return True

    def remove(self, skill_id: str) -> bool:
        with self._lock:
            return self._skills.pop(skill_id, None) is not None

    def get(self, skill_id: str) -> Optional[Skill]:
        with self._lock:
            return self._skills.get(skill_id)

    def all(self) -> List[Skill]:
        with self._lock:
            return list(self._skills.values())

    def capabilities_field(self) -> List[str]:
        """Return the list of skill names suitable for mesh_nodes.capabilities."""
        with self._lock:
            return sorted({s.name for s in self._skills.values()})

    def find_best(self, criteria: str) -> Optional[Skill]:
        """Naive best-match: name or tag contains criteria (case-insensitive)."""
        crit = criteria.lower()
        with self._lock:
            candidates = [
                s for s in self._skills.values()
                if crit in s.name.lower()
                or any(crit in t.lower() for t in s.tags)
                or crit in s.description.lower()
            ]
        if not candidates:
            return None
        candidates.sort(key=lambda s: s.confidence, reverse=True)
        return candidates[0]

    # -- listeners ---------------------------------------------------------

    def on_skill_added(self, cb: Callable[[Skill], None]) -> None:
        self._listeners.append(cb)


# ---------------------------------------------------------------------------
# Skill Sync (network broadcast / receive) — MemorySync pattern
# ---------------------------------------------------------------------------

class SkillSync:
    """
    Broadcasts newly-learned skills to peers over UDP and receives incoming
    skill announcements on a listening socket.  UDP keeps it lightweight and
    fire-and-forget, matching the MemorySync gossip style.

    Protocol: newline-delimited JSON envelopes.

    Envelope types:
      {"type":"skill_announce","skill":{...},"origin":agent_id,"ttl":3}
      {"type":"skill_request","origin":agent_id}      # ask peers for full set
      {"type":"skill_dump","skills":[...],"origin":agent_id}
    """

    DEFAULT_TTL = 3
    BUFFER_SIZE = 65536

    def __init__(
        self,
        agent_id: str,
        registry: SkillRegistry,
        listen_host: str = "127.0.0.1",
        listen_port: int = 0,
    ):
        self.agent_id = agent_id
        self.registry = registry
        self.listen_host = listen_host
        self.listen_port = listen_port
        self.peers: Dict[str, PeerInfo] = {}
        self._peers_lock = threading.Lock()
        self._seen_msg_ids: Set[str] = set()
        self._seen_lock = threading.Lock()
        self._running = threading.Event()
        self._sock: Optional[socket.socket] = None
        self._thread: Optional[threading.Thread] = None

        # Whenever a skill is added locally, broadcast it.
        self.registry.on_skill_added(self._on_local_skill)

    # -- peer management ---------------------------------------------------

    def add_peer(self, peer: PeerInfo) -> None:
        with self._peers_lock:
            self.peers[peer.agent_id] = peer
        log.info("[%s] peer added: %s @ %s:%s", self.agent_id, peer.agent_id, peer.host, peer.port)

    def remove_peer(self, agent_id: str) -> None:
        with self._peers_lock:
            self.peers.pop(agent_id, None)

    def _peer_list(self) -> List[PeerInfo]:
        with self._peers_lock:
            return list(self.peers.values())

    # -- lifecycle ---------------------------------------------------------

    def start(self) -> None:
        if self._running.is_set():
            return
        self._sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        self._sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        self._sock.bind((self.listen_host, self.listen_port))
        self.listen_port = self._sock.getsockname()[1]
        self._running.set()
        self._thread = threading.Thread(target=self._listen_loop, daemon=True, name=f"skillsync-{self.agent_id}")
        self._thread.start()
        log.info("[%s] SkillSync listening on %s:%s", self.agent_id, self.listen_host, self.listen_port)

    def stop(self) -> None:
        self._running.clear()
        if self._sock:
            try:
                self._sock.close()
            except OSError:
                pass
        if self._thread:
            self._thread.join(timeout=2)

    # -- sending -----------------------------------------------------------

    def _send(self, envelope: dict, peer: PeerInfo) -> None:
        data = (json.dumps(envelope) + "\n").encode("utf-8")
        try:
            with socket.socket(socket.AF_INET, socket.SOCK_DGRAM) as s:
                s.sendto(data, peer.addr())
        except OSError as exc:
            log.warning("[%s] send to %s failed: %s", self.agent_id, peer.agent_id, exc)

    def _broadcast(self, envelope: dict) -> None:
        for peer in self._peer_list():
            self._send(envelope, peer)

    def _on_local_skill(self, skill: Skill) -> None:
        """Triggered by registry when a skill is added locally."""
        if skill.source_agent and skill.source_agent != self.agent_id:
            # Came from a peer — still re-broadcast if TTL allows (gossip).
            pass
        envelope = {
            "type": "skill_announce",
            "msg_id": str(uuid.uuid4()),
            "origin": self.agent_id,
            "ttl": self.DEFAULT_TTL,
            "skill": skill.to_dict(),
        }
        self._broadcast(envelope)

    def announce_all(self) -> None:
        """Send a skill_dump of everything we know to all peers."""
        envelope = {
            "type": "skill_dump",
            "msg_id": str(uuid.uuid4()),
            "origin": self.agent_id,
            "ttl": 0,
            "skills": [s.to_dict() for s in self.registry.all()],
        }
        self._broadcast(envelope)

    def request_skills(self) -> None:
        """Ask peers to dump their skills."""
        envelope = {
            "type": "skill_request",
            "msg_id": str(uuid.uuid4()),
            "origin": self.agent_id,
            "ttl": 0,
        }
        self._broadcast(envelope)

    # -- receiving ---------------------------------------------------------

    def _listen_loop(self) -> None:
        assert self._sock is not None
        while self._running.is_set():
            try:
                data, _addr = self._sock.recvfrom(self.BUFFER_SIZE)
            except OSError:
                break
            for line in data.decode("utf-8", errors="replace").splitlines():
                line = line.strip()
                if not line:
                    continue
                try:
                    envelope = json.loads(line)
                except json.JSONDecodeError:
                    continue
                try:
                    self._handle_envelope(envelope)
                except Exception:
                    log.exception("[%s] error handling envelope", self.agent_id)

    def _seen(self, msg_id: str) -> bool:
        with self._seen_lock:
            if msg_id in self._seen_msg_ids:
                return True
            self._seen_msg_ids.add(msg_id)
            # prune
            if len(self._seen_msg_ids) > 5000:
                self._seen_msg_ids = set(list(self._seen_msg_ids)[-2500:])
            return False

    def _handle_envelope(self, env: dict) -> None:
        msg_id = env.get("msg_id", str(uuid.uuid4()))
        if self._seen(msg_id):
            return

        origin = env.get("origin", "?")
        if origin == self.agent_id:
            return  # don't process our own loopback

        etype = env.get("type")

        if etype == "skill_announce":
            skill = Skill.from_dict(env["skill"])
            # Register without triggering another broadcast if unchanged.
            changed = self.registry.add(skill, notify=True)
            # Gossip forward if TTL > 1
            ttl = env.get("ttl", 0)
            if changed and ttl and ttl > 1:
                env["ttl"] = ttl - 1
                env["msg_id"] = str(uuid.uuid4())
                self._broadcast(env)

        elif etype == "skill_dump":
            for sd in env.get("skills", []):
                self.registry.add(Skill.from_dict(sd), notify=True)

        elif etype == "skill_request":
            # Respond with our full dump to the requester (best-effort).
            self.announce_all()

        else:
            log.debug("[%s] unknown envelope type: %s", self.agent_id, etype)


# ---------------------------------------------------------------------------
# Mesh node integration helper
# ---------------------------------------------------------------------------

class MeshNodeCapabilities:
    """
    Bridges SkillRegistry into the mesh_nodes.capabilities field.

    In the real A2A Mesh repo this would update the DB row for the node;
    here we keep an in-memory representation that mirrors the schema.
    """

    def __init__(self, agent_id: str, registry: SkillRegistry):
        self.agent_id = agent_id
        self.registry = registry

    def snapshot(self) -> dict:
        return {
            "agent_id": self.agent_id,
            "capabilities": self.registry.capabilities_field(),
            "skill_count": len(self.registry.all()),
            "updated_at": datetime.now(timezone.utc).isoformat(),
        }

    def delegate(self, task_description: str) -> Optional[Skill]:
        """Find the best local skill for a task description."""
        return self.registry.find_best(task_description)


# ---------------------------------------------------------------------------
# Demo / self-test
# ---------------------------------------------------------------------------

def _demo() -> None:
    """
    Spin up three in-process agents, have one learn a skill, and verify
    that the other two receive it via the gossip broadcast.
    """

    agents: Dict[str, SkillSync] = {}

    def make_agent(aid: str, port: int) -> SkillSync:
        reg = SkillRegistry(owner_agent_id=aid)
        sync = SkillSync(agent_id=aid, registry=reg, listen_host="127.0.0.1", listen_port=port)
        sync.start()
        agents[aid] = sync
        return sync

    a = make_agent("agent_alpha", 0)
    b = make_agent("agent_beta", 0)
    c = make_agent("agent_gamma", 0)

    # Wire peers (full mesh for demo)
    for sync in agents.values():
        for other_id, other in agents.items():
            if other_id == sync.agent_id:
                continue
            sync.add_peer(PeerInfo(
                agent_id=other_id,
                host=other.listen_host,
                port=other.listen_port,
            ))

    time.sleep(0.3)  # let sockets settle

    print("\n=== Initial state ===")
    for aid, sync in agents.items():
        print(f"  {aid}: capabilities={sync.registry.capabilities_field()}")

    # Agent alpha learns a new skill
    new_skill = Skill(
        skill_id=str(uuid.uuid4()),
        name="summarize_pdf",
        description="Extract and summarize text from PDF documents.",
        version="1.0.0",
        tags=["pdf", "nlp", "summary"],
        source_agent="agent_alpha",
        learned_at=datetime.now(timezone.utc).isoformat(),
        confidence=0.92,
        payload={"max_pages": 200},
    )
    print(f"\n=== {a.agent_id} learns skill: {new_skill.name} ===")
    a.registry.add(new_skill)

    # Wait for gossip propagation
    time.sleep(1.0)

    print("\n=== After sync ===")
    for aid, sync in agents.items():
        caps = sync.registry.capabilities_field()
        print(f"  {aid}: capabilities={caps}  count={len(sync.registry.all())}")

    # Verify
    for aid, sync in agents.items():
        s = sync.registry.find_best("pdf")
        assert s is not None, f"{aid} did not receive summarize_pdf!"
        print(f"  [OK] {aid} has skill '{s.name}' from {s.source_agent}")

    # Demonstrate capabilities snapshot + delegation
    print("\n=== Capabilities snapshots ===")
    for aid, sync in agents.items():
        cap = MeshNodeCapabilities(aid, sync.registry)
        print(f"  {json.dumps(cap.snapshot())}")

    print("\n=== Delegation test ===")
    cap = MeshNodeCapabilities("agent_beta", b.registry)
    chosen = cap.delegate("I need to summarize a pdf")
    print(f"  delegated to skill: {chosen.name if chosen else 'NONE'}")

    # Agent gamma learns a *different* skill -> should propagate too
    skill2 = Skill(
        skill_id=str(uuid.uuid4()),
        name="translate_hu_en",
        description="Translate Hungarian text to English.",
        version="1.0.0",
        tags=["translation", "hu", "en"],
        source_agent="agent_gamma",
        learned_at=datetime.now(timezone.utc).isoformat(),
        confidence=0.85,
    )
    print(f"\n=== agent_gamma learns skill: {skill2.name} ===")
    c.registry.add(skill2)
    time.sleep(1.0)

    print("\n=== Final state ===")
    for aid, sync in agents.items():
        print(f"  {aid}: {sync.registry.capabilities_field()}")

    # Cleanup
    for sync in agents.values():
        sync.stop()

    print("\nDemo complete. All agents synced skills successfully.")


if __name__ == "__main__":
    _demo()